pub fn myfun4(x: &Vec<u64>, y: &mut Vec<u64>) {
    // Ensure the output vector is empty before we start
    y.clear();

    // Iterate over each value in `x` and push those divisible by 3 into `y`
    for &val in x.iter() {
        if val % 3 == 0 {
            y.push(val);
        }
    }
}

